export const DICTS: Record<Lang, Dict> = { fr, en, ar };

export function makeFmt(lang: Lang): Fmt {
  const loc = LOCALE[lang];
  const nf = (d: number) => new Intl.NumberFormat(loc, { minimumFractionDigits: d, maximumFractionDigits: d, numberingSystem: "latn" });
  const dash = "—";
  return {
    num: (v, d = 2) => (v == null || !Number.isFinite(v) ? dash : nf(d).format(v)),
    pct: (v, d = 1) => (v == null || !Number.isFinite(v) ? dash : new Intl.NumberFormat(loc, { style: "percent", minimumFractionDigits: d, maximumFractionDigits: d, numberingSystem: "latn" }).format(v)),
    km2: (v) => (v == null || !Number.isFinite(v) ? dash : `${nf(v < 1 ? 3 : 2).format(v)} km²`),
    date: (iso) => {
      if (!iso) return dash;
      const d = new Date(iso.length === 10 ? `${iso}T00:00:00Z` : iso);
      return Number.isNaN(d.getTime()) ? iso : new Intl.DateTimeFormat(loc, { day: "numeric", month: "short", year: "numeric", timeZone: "UTC", numberingSystem: "latn" }).format(d);
    },
    coord: (lon, lat) => `${Math.abs(lat).toFixed(4)}° ${lat >= 0 ? "N" : "S"}, ${Math.abs(lon).toFixed(4)}° ${lon >= 0 ? "E" : "W"}`,
  };
}

export function translate(lang: Lang, key: string, params: Params = {}): string {
  const entry = DICTS[lang][key] ?? DICTS.en[key];
  if (entry === undefined) return key;
  return typeof entry === "function" ? entry(params, makeFmt(lang)) : entry;
}
